/**
 * "Copy as command" (FP-4, CT-15): a publish or a subscription as a mosquitto or MQTTX CLI
 * command line (pure, no Vue).
 *
 * Flags follow mosquitto_pub(1) / mosquitto_sub(1) (2.0) and the MQTTX CLI reference:
 * - connection: host, port, protocol version, the client id only when it is fixed (not empty,
 *   not generated by mqtey), the user name; the password only as an environment variable
 *   (`"$MQTT_PASSWORD"` on POSIX shells, `$env:MQTT_PASSWORD` on PowerShell), never inlined;
 * - TLS: CA file (else the OS certificates: mosquitto enables TLS only with a CA option), client
 *   certificate and key, `--insecure` when the server certificate is not verified, ALPN;
 * - publish: topic, QoS, retain, payload (`-n` for an empty one with mosquitto) and, on
 *   MQTT 5, user properties, content type, response topic, correlation data, message expiry,
 *   payload format indicator;
 * - subscribe: filter, QoS and, on MQTT 5, the subscription options the tool supports
 *   (mosquitto_sub: retain as published, retain handling (2.1+); MQTTX: no local, retain as
 *   published, retain handling, subscription identifier).
 *
 * Quoting and the connection flags are in `./cli-arguments`. PowerShell
 * output targets PowerShell 7.3+: Windows PowerShell 5.1 strips the double quotes of native
 * arguments, so a JSON payload needs `\"` there (`warning` says so).
 *
 * Refused (`{ ok: false }`): mosquitto with ws / wss (only MQTTX connects over WebSockets),
 * payloads that are not valid UTF-8, NUL characters, MQTTX user properties containing ': ', and
 * commands longer than `MAX_COMMAND_LENGTH`.
 *
 * Every "Copy as command" menu of a publish (a message, a history entry) uses one model:
 * `commandMenuItems` (one item per tool, disabled with the generator's reason) and `copiedToast`
 * (the toast after a copy: the password variable and the shell caveat, e.g. PowerShell 5.1).
 */
import type { ConnectionProfile, PublishProperties, QoS, Subscription } from '@shared/models'
import { isWebSocketProtocol } from '@shared/defaults'
import { CommandLine, connectionFlags, PASSWORD_VARIABLE, type CliShell } from './cli-arguments'
import { cleanPublishProperties } from './publish'

export { PASSWORD_VARIABLE, quoteArgument, type CliShell } from './cli-arguments'

export type CliResult =
  | {
      ok: true
      command: string
      /** e.g. 'MQTT_PASSWORD' when the profile has a password (set it before running). */
      passwordVariable?: string
      /** A caveat for this shell, e.g. Windows PowerShell 5.1 and JSON quotes. */
      warning?: string
    }
  | { ok: false; error: string }

export interface PublishCommandInput {
  profile: ConnectionProfile
  topic: string
  payload: Uint8Array
  qos: QoS
  retain: boolean
  properties?: PublishProperties
}

export interface SubscribeCommandInput {
  profile: ConnectionProfile
  subscription: Subscription
}

/** Longest command copied (Windows command lines hold at most 32,767 characters). */
export const MAX_COMMAND_LENGTH = 32_000

const BINARY_ERROR = 'Binary payloads cannot be copied as a command yet'
const PS_51_WARNING =
  'Needs PowerShell 7.3 or later: Windows PowerShell 5.1 drops the double quotes of the payload'

/** PowerShell on Windows, a POSIX shell (bash, zsh…) elsewhere. */
export function defaultCliShell(platform: string): CliShell {
  return platform === 'win32' ? 'powershell' : 'posix'
}

const RETAIN_HANDLING = ['always', 'new', 'never'] as const

function finish(
  line: CommandLine,
  profile: ConnectionProfile,
  shell: CliShell,
  texts: readonly string[]
): CliResult {
  if (texts.some((text) => text.includes('\u0000'))) {
    return { ok: false, error: 'Text with a NUL character cannot be copied as a command' }
  }
  const command = line.toString()
  if (command.length > MAX_COMMAND_LENGTH) {
    return { ok: false, error: 'The message is too large to copy as a command' }
  }
  const result: CliResult = { ok: true, command }
  if (profile.password !== '') result.passwordVariable = PASSWORD_VARIABLE
  if (shell === 'powershell' && texts.some((text) => text.includes('"'))) {
    result.warning = PS_51_WARNING
  }
  return result
}

function decodeUtf8(payload: Uint8Array): string | null {
  try {
    return new TextDecoder('utf-8', { fatal: true }).decode(payload)
  } catch {
    return null
  }
}

/** A publish as a mosquitto_pub or MQTTX command. */
export function publishCommand(
  input: PublishCommandInput,
  tool: 'mosquitto_pub' | 'mqttx',
  shell: CliShell
): CliResult {
  const { profile } = input
  const mqttx = tool === 'mqttx'
  if (!mqttx && isWebSocketProtocol(profile.protocol)) {
    return {
      ok: false,
      error: 'mosquitto_pub cannot connect over WebSockets: copy the MQTTX command instead'
    }
  }
  const message = decodeUtf8(input.payload)
  if (message === null) return { ok: false, error: BINARY_ERROR }
  const properties =
    profile.protocolVersion === 5 ? cleanPublishProperties(input.properties) : undefined
  const userProperties = properties?.userProperties ?? []
  if (mqttx && userProperties.some((p) => p.key.includes(': ') || p.value.includes(': '))) {
    return { ok: false, error: "MQTTX cannot send user properties that contain ': '" }
  }

  const line = new CommandLine(mqttx ? 'mqttx pub' : 'mosquitto_pub', shell)
  connectionFlags(line, profile, mqttx)
  line.option('-t', input.topic)
  if (input.qos > 0) line.option('-q', String(input.qos))
  if (input.retain) line.flag('-r')
  const texts = [input.topic, message, profile.host, profile.username]
  if (properties) {
    if (properties.payloadFormatIndicator) {
      if (mqttx) line.flag('-pf')
      else line.option('-D', 'publish', 'payload-format-indicator', '1')
    }
    const expiry = properties.messageExpiryInterval
    if (expiry !== undefined) {
      if (mqttx) line.option('-e', String(expiry))
      else line.option('-D', 'publish', 'message-expiry-interval', String(expiry))
    }
    const strings: Array<[mqttxFlag: string, property: string, value: string | undefined]> = [
      ['-ct', 'content-type', properties.contentType],
      ['-rt', 'response-topic', properties.responseTopic],
      ['-cd', 'correlation-data', properties.correlationData]
    ]
    for (const [mqttxFlag, property, value] of strings) {
      if (value === undefined) continue
      texts.push(value)
      if (mqttx) line.option(mqttxFlag, value)
      else line.option('-D', 'publish', property, value)
    }
    for (const { key, value } of userProperties) {
      texts.push(key, value)
      if (mqttx) line.option('-up', `${key}: ${value}`)
      else line.option('-D', 'publish', 'user-property', key, value)
    }
  }
  if (!mqttx && message === '') line.flag('-n')
  else line.option('-m', message)
  return finish(line, profile, shell, texts)
}

/** A subscription as a mosquitto_sub or MQTTX command (prints the topic of each message). */
export function subscribeCommand(
  input: SubscribeCommandInput,
  tool: 'mosquitto_sub' | 'mqttx',
  shell: CliShell
): CliResult {
  const { profile, subscription } = input
  const mqttx = tool === 'mqttx'
  if (!mqttx && isWebSocketProtocol(profile.protocol)) {
    return {
      ok: false,
      error: 'mosquitto_sub cannot connect over WebSockets: copy the MQTTX command instead'
    }
  }
  const line = new CommandLine(mqttx ? 'mqttx sub' : 'mosquitto_sub', shell)
  connectionFlags(line, profile, mqttx)
  line.option('-t', subscription.topic)
  if (subscription.qos > 0) line.option('-q', String(subscription.qos))
  if (profile.protocolVersion === 5) {
    const identifier = subscription.subscriptionIdentifier
    if (mqttx) {
      if (subscription.noLocal) line.flag('-nl')
      if (subscription.retainAsPublished) line.flag('-rap')
      if (subscription.retainHandling !== 0) line.option('-rh', String(subscription.retainHandling))
      if (identifier !== undefined && identifier > 0) line.option('-si', String(identifier))
    } else {
      // mosquitto_sub has no no-local or subscription identifier option.
      if (subscription.retainAsPublished) line.flag('--retain-as-published')
      if (subscription.retainHandling !== 0) {
        line.option('--retain-handling', RETAIN_HANDLING[subscription.retainHandling])
      }
    }
  }
  if (!mqttx) line.flag('-v')
  return finish(line, profile, shell, [subscription.topic, profile.host, profile.username])
}

// ---------------------------------------------------------------------------
// The "Copy as command" submenu of a publish (a message, a history entry)
// ---------------------------------------------------------------------------

export type CommandTool = 'mosquitto_pub' | 'mqttx'

export interface CommandMenuItem {
  tool: CommandTool
  /** Item label: `mosquitto_pub` / `mqttx pub`. */
  label: string
  testId: 'copy-as-mosquitto' | 'copy-as-mqttx'
  result: CliResult
  /** Why the command cannot be copied (the item is disabled and shows it). */
  reason?: string
}

const PUBLISH_TOOLS: ReadonlyArray<Pick<CommandMenuItem, 'tool' | 'label' | 'testId'>> = [
  { tool: 'mosquitto_pub', label: 'mosquitto_pub', testId: 'copy-as-mosquitto' },
  { tool: 'mqttx', label: 'mqttx pub', testId: 'copy-as-mqttx' }
]

/** The reason of both items when the connection no longer exists. */
export const NO_PROFILE_ERROR = 'The connection no longer exists'

/**
 * The submenu items for a publish: `input` is the generator input, an `{ error }` when the
 * publish itself cannot be built (e.g. an invalid history entry), or null without a profile.
 */
export function commandMenuItems(
  input: PublishCommandInput | { error: string } | null,
  shell: CliShell
): CommandMenuItem[] {
  return PUBLISH_TOOLS.map((tool) => {
    const result: CliResult =
      input === null
        ? { ok: false, error: NO_PROFILE_ERROR }
        : 'error' in input
          ? { ok: false, error: input.error }
          : publishCommand(input, tool.tool, shell)
    return result.ok ? { ...tool, result } : { ...tool, result, reason: result.error }
  })
}

/**
 * The toast after a copy: 'Command copied', plus what to know before running the command (the
 * password variable to set, the shell caveat such as Windows PowerShell 5.1 and JSON quotes).
 */
export function copiedToast(result: Extract<CliResult, { ok: true }>): {
  title: string
  description?: string
} {
  const notes: string[] = []
  if (result.passwordVariable) notes.push(`Password not included — set ${result.passwordVariable}`)
  if (result.warning) notes.push(result.warning)
  return notes.length > 0
    ? { title: 'Command copied', description: notes.join('. ') }
    : { title: 'Command copied' }
}
